import{_ as e,o as a,c as o,a2 as s}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"🌱 kiwa v0.5 — polyglot test toolchain · Coverage + Mutation gates · 8 component adapters","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v0.5/gh-discussions-announcement.md","filePath":"announcements/v0.5/gh-discussions-announcement.md"}'),r={name:"announcements/v0.5/gh-discussions-announcement.md"};function i(n,t,d,c,l,h){return a(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="🌱-kiwa-v0-5-—-polyglot-test-toolchain-·-coverage-mutation-gates-·-8-component-adapters" tabindex="-1">🌱 kiwa v0.5 — polyglot test toolchain · Coverage + Mutation gates · 8 component adapters <a class="header-anchor" href="#🌱-kiwa-v0-5-—-polyglot-test-toolchain-·-coverage-mutation-gates-·-8-component-adapters" aria-label="Permalink to &quot;🌱 kiwa v0.5 — polyglot test toolchain · Coverage + Mutation gates · 8 component adapters&quot;">​</a></h1><p>A scattered test stack is the default. Contract tests live in Foundry, unit + API in Vitest, e2e in Playwright, components in Testing Library, a11y in axe-core, visual in pixelmatch, Python services in pytest. Every runner has its own conventions, fixtures, and gates — and <strong>no single source of truth</strong> ties them together.</p><p>kiwa v0.5 is the cut where I finally feel the toolchain solves that. <strong>One Layer 1 spec → every test layer your stack actually needs, across TypeScript, Python, and Solidity.</strong></p><h2 id="_1-six-test-surfaces-one-spec" tabindex="-1">1. Six test surfaces, one spec <a class="header-anchor" href="#_1-six-test-surfaces-one-spec" aria-label="Permalink to &quot;1. Six test surfaces, one spec&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Stacks</th></tr></thead><tbody><tr><td>Contract</td><td>Foundry / Hardhat (Solidity)</td></tr><tr><td>API integration</td><td>msw / supertest / Vitest</td></tr><tr><td>Component</td><td><code>@kiwa-lab/ui</code> ships <strong>8 adapters</strong> (see § 2)</td></tr><tr><td>E2E</td><td>Playwright + anvil + viem + EIP-6963 + ERC-4337</td></tr><tr><td>A11y + Visual</td><td>axe-core / pixelmatch</td></tr><tr><td>Data + CLI + Observability</td><td>queue / cron / shell IO / flaky detection</td></tr></tbody></table><p>dApps and smart contracts are first-class — but so is everything else.</p><h2 id="_2-kiwa-lab-ui-covers-8-component-surfaces-from-one-package" tabindex="-1">2. <code>@kiwa-lab/ui</code> covers 8 component surfaces from one package <a class="header-anchor" href="#_2-kiwa-lab-ui-covers-8-component-surfaces-from-one-package" aria-label="Permalink to &quot;2. \`@kiwa-lab/ui\` covers 8 component surfaces from one package&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Framework</th><th>Helper</th></tr></thead><tbody><tr><td>React</td><td><code>setupComponentEnv</code></td></tr><tr><td>Vue 3</td><td><code>setupVueComponentEnv</code></td></tr><tr><td>Svelte</td><td><code>setupSvelteComponentEnv</code></td></tr><tr><td>SolidJS</td><td><code>setupSolidComponentEnv</code></td></tr><tr><td>Lit (Web Components)</td><td><code>setupLitComponentEnv</code></td></tr><tr><td>Qwik (resumable)</td><td><code>setupQwikComponentEnv</code></td></tr><tr><td>Angular</td><td><code>setupAngularComponentEnv</code></td></tr><tr><td>Browser (real Chromium)</td><td><code>setupBrowserComponentEnv</code></td></tr></tbody></table><p>All share the same <code>mode (render / interaction / snapshot) + stop()</code> contract. Optional peer deps mean you only install what you actually use.</p><h2 id="_3-polyglot-from-day-one" tabindex="-1">3. Polyglot from day one <a class="header-anchor" href="#_3-polyglot-from-day-one" aria-label="Permalink to &quot;3. Polyglot from day one&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Language</th><th>Packages</th><th>Notes</th></tr></thead><tbody><tr><td>TypeScript</td><td>11 npm packages</td><td>Primary surface — every adapter</td></tr><tr><td>Python</td><td>1 PyPI package (<code>kiwa-test-py</code>)</td><td><code>@kiwa-lab/spec</code> Python port + requests / httpx adapter</td></tr><tr><td>Solidity</td><td>Foundry / Hardhat bridges</td><td><code>/kiwa-forge</code> + <code>/kiwa-hardhat</code> from the same Layer 1 spec</td></tr></tbody></table><p>Rust / Go on the roadmap. The point: <strong>spec once, generate test layers across the languages your stack actually uses.</strong></p><h2 id="_4-release-time-gates-that-actually-fire" tabindex="-1">4. Release-time gates that actually fire <a class="header-anchor" href="#_4-release-time-gates-that-actually-fire" aria-label="Permalink to &quot;4. Release-time gates that actually fire&quot;">​</a></h2><p><code>scripts/check-coverage-gates.mjs</code> + <code>scripts/check-mutation-gates.mjs</code> run inside <code>.github/workflows/release.yml</code> and <strong>block publish</strong> if any package regresses below its threshold.</p><h3 id="coverage-gate" tabindex="-1">Coverage gate <a class="header-anchor" href="#coverage-gate" aria-label="Permalink to &quot;Coverage gate&quot;">​</a></h3><p>Lines / Statements / Functions ≥ 90 %, Branches ≥ 80 %, across all 11 packages.</p><h3 id="mutation-gate-—-mutation-score-indicator-msi" tabindex="-1">Mutation gate — <a href="https://stryker-mutator.io/docs/mutation-testing-elements/mutation-score-indicator/" target="_blank" rel="noreferrer">Mutation Score Indicator (MSI)</a> <a class="header-anchor" href="#mutation-gate-—-mutation-score-indicator-msi" aria-label="Permalink to &quot;Mutation gate — [Mutation Score Indicator (MSI)](https://stryker-mutator.io/docs/mutation-testing-elements/mutation-score-indicator/)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Package</th><th>MSI</th><th>Threshold</th></tr></thead><tbody><tr><td><code>@kiwa-lab/api</code></td><td><strong>96.06 %</strong></td><td>90</td></tr><tr><td><code>@kiwa-lab/a11y</code></td><td><strong>93.62 %</strong></td><td>90</td></tr><tr><td><code>@kiwa-lab/ui</code></td><td><strong>91.76 %</strong></td><td>80</td></tr><tr><td><code>@kiwa-lab/cli-test</code></td><td>89.69 %</td><td>80</td></tr><tr><td><code>@kiwa-lab/data</code></td><td>86.93 %</td><td>80</td></tr><tr><td><code>@kiwa-lab/spec</code></td><td>85.51 %</td><td>80</td></tr><tr><td><code>@kiwa-lab/core</code></td><td>85.09 %</td><td>80</td></tr><tr><td><code>@kiwa-lab/cli</code></td><td>84.44 %</td><td>80</td></tr><tr><td><code>@kiwa-lab/e2e</code></td><td>84.21 %</td><td>80</td></tr><tr><td><code>@kiwa-lab/observability</code></td><td>84.12 %</td><td>80</td></tr><tr><td><code>@kiwa-lab/visual</code></td><td>83.02 %</td><td>80</td></tr></tbody></table><p>Per-package thresholds are intentional — pure-logic packages enforce 90; thin wrappers around third-party libs hold at 80 to avoid getting trapped by equivalent mutants.</p><h2 id="try-it" tabindex="-1">Try it <a class="header-anchor" href="#try-it" aria-label="Permalink to &quot;Try it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-lab/core</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or for Python services</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kiwa-test-py</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># scaffold everything</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dlx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-lab/cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><ul><li>📖 README · <a href="https://github.com/cardene777/kiwa" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa</a></li><li>📦 npm · <a href="https://www.npmjs.com/package/@kiwa-lab/core" target="_blank" rel="noreferrer">https://www.npmjs.com/package/@kiwa-lab/core</a></li><li>🐍 PyPI · <a href="https://pypi.org/project/kiwa-test-py/" target="_blank" rel="noreferrer">https://pypi.org/project/kiwa-test-py/</a></li><li>🎬 80s overview · <code>assets/kiwa-promo-en.mp4</code> (see README inline)</li></ul><h2 id="how-can-you-help" tabindex="-1">How can you help? <a class="header-anchor" href="#how-can-you-help" aria-label="Permalink to &quot;How can you help?&quot;">​</a></h2><ul><li>Try it on a stack with <strong>mixed test surfaces</strong> (dApp + API + a11y, or Python service + REST contract, or a multi-framework UI). File an Issue / Discussion if anything breaks or feels awkward.</li><li>Adapter contributions welcome — <code>@kiwa-lab/ui</code> is purpose-built for new framework adapters (the SolidJS adapter took 1 PR and 100 LOC).</li><li>Polyglot bridges are the most strategic contribution surface. Rust / Go ports of <code>@kiwa-lab/spec</code> are on the roadmap — let&#39;s talk in this thread if you want to drive one.</li><li>Ideas for new test surfaces (gRPC mock / Pact contract test / Storybook visual diff) — discuss in an Idea Discussion.</li></ul><p>Thanks for reading 🌱</p><p>— @cardene777</p>`,26)])])}const g=e(r,[["render",i]]);export{u as __pageData,g as default};
